create or replace function concierge.validate_presentation_shape(v jsonb,s jsonb) returns void language plpgsql set search_path='' as $$
declare k text;item jsonb;t text:=s->>'type';n numeric;begin
 if v='null'::jsonb and coalesce((s->>'nullable')::boolean,false) then return;end if;
 if t='object' then
  if jsonb_typeof(v) is distinct from 'object' or exists(select 1 from jsonb_object_keys(v) j(k) where not (s->'fields' ? j.k)) then perform concierge.fail('invalid_input');end if;
  for k in select jsonb_object_keys(s->'fields') loop
   if v ? k then perform concierge.validate_presentation_shape(v->k,s->'fields'->k);
   elsif not coalesce((s->'fields'->k->>'optional')::boolean,false) then perform concierge.fail('invalid_input');end if;
  end loop;
 elsif t='array' then
  if jsonb_typeof(v) is distinct from 'array' then perform concierge.fail('invalid_input');end if;
  if jsonb_array_length(v) not between coalesce((s->>'min')::integer,0) and (s->>'max')::integer then perform concierge.fail('invalid_input');end if;
  if coalesce((s->>'unique')::boolean,false) and (select count(distinct value) from jsonb_array_elements(v))<>jsonb_array_length(v) then perform concierge.fail('invalid_input');end if;
  for item in select value from jsonb_array_elements(v) loop perform concierge.validate_presentation_shape(item,s->'item');end loop;
 elsif t='text' then
  perform concierge.txt(jsonb_build_object('v',v),'v',(s->>'max')::integer,coalesce((s->>'empty')::boolean,false));
  if (v#>>'{}') ~ '<[^>]*>' then perform concierge.fail('invalid_input');end if;
 elsif t='identifier' then perform concierge.identifier(concierge.txt(jsonb_build_object('v',v),'v',100));
 elsif t='integer' then
  n:=concierge.integer(jsonb_build_object('v',v),'v');if n not between (s->>'min')::numeric and (s->>'max')::numeric then perform concierge.fail('invalid_input');end if;
 elsif t='date' then perform concierge.day(jsonb_build_object('v',v),'v');
 elsif t in ('url','image') then
  perform concierge.presentation_url(concierge.txt(jsonb_build_object('v',v),'v',2048),t='image');
 elsif t='boolean' then
  if jsonb_typeof(v) is distinct from 'boolean' then perform concierge.fail('invalid_input');end if;
 elsif t='enum' then
  if v is null or not (s->'values' @> jsonb_build_array(v)) then perform concierge.fail('invalid_input');end if;
 else perform concierge.fail('invalid_input');end if;
end $$;

create or replace function concierge.validate_items(items jsonb) returns void language plpgsql set search_path='' as $$ declare r jsonb; k text; ids text[]:='{}';slots text[]:='{}'; begin
 if jsonb_typeof(items) is distinct from 'array' then perform concierge.fail('invalid_input'); end if;
 if jsonb_array_length(items)>50 then perform concierge.fail('invalid_input'); end if;
 for r in select value from jsonb_array_elements(items) loop
  perform concierge.keys(r,array['id','slot','currentProductId','proposedProductId','priceCents','currency','rationale']);
  foreach k in array array['id','slot','proposedProductId'] loop perform concierge.identifier(concierge.txt(r,k,100)); end loop;
  if r->'currentProductId' <> 'null'::jsonb then perform concierge.identifier(concierge.txt(r,'currentProductId',100));end if;
  perform concierge.txt(r,'rationale',4000);
  if concierge.txt(r,'currency',3)<>'USD' or concierge.integer(r,'priceCents')>100000000 then perform concierge.fail('invalid_input'); end if;
  if (r->>'id')=any(ids) or (r->>'slot')=any(slots) then perform concierge.fail('invalid_input'); end if;
  ids:=array_append(ids,r->>'id');slots:=array_append(slots,r->>'slot');
 end loop;
end $$;

create or replace function concierge.validate_presentation(p jsonb,baseline jsonb,recs jsonb default null,intake boolean default false) returns void language plpgsql set search_path='' as $$
declare s jsonb;c jsonb;r jsonb;g jsonb;steps jsonb:=p->'baselineRoutine';cards jsonb:=p->'categoryCards';pid text;begin
 perform concierge.validate_presentation_shape(p,concierge.presentation_shape(intake));
 if (select count(distinct x->>'id') from jsonb_array_elements(steps)j(x))<>jsonb_array_length(steps) then perform concierge.fail('invalid_input');end if;
 for s in select value from jsonb_array_elements(steps) loop
  if s->>'kind'='instruction' then
   if s->'slot'<>'null'::jsonb or s->'productId'<>'null'::jsonb or s->'product'<>'null'::jsonb then perform concierge.fail('invalid_input');end if;
  elsif s->'slot'='null'::jsonb or s->'productId'='null'::jsonb or s->'product'='null'::jsonb or s->>'productId' is distinct from s->'product'->>'id' then perform concierge.fail('invalid_input');end if;
 end loop;
 if (select count(*) from jsonb_array_elements(steps)j(x) where x->>'kind'='product')<>jsonb_array_length(baseline) or exists(
  select 1 from jsonb_array_elements(baseline)j(b) where (select count(*) from jsonb_array_elements(steps)j(x) where x->>'kind'='product' and x->>'slot'=b->>'slot' and x->>'productId'=b->>'productId')<>1) then perform concierge.fail('invalid_input');end if;
 if intake then return;end if;
 if (select count(distinct x->>'id') from jsonb_array_elements(cards)j(x))<>jsonb_array_length(cards) or (select count(distinct x->>'slot') from jsonb_array_elements(cards)j(x))<>jsonb_array_length(cards) then perform concierge.fail('invalid_input');end if;
 if (select count(*) from jsonb_array_elements(cards)j(x) where x->>'recommendationId' is not null)<>(select count(distinct x->>'recommendationId') from jsonb_array_elements(cards)j(x)) then perform concierge.fail('invalid_input');end if;
 if jsonb_array_length(steps)+(select count(*) from jsonb_array_elements(cards)j(x) where x->>'kind'='addition')>50 then perform concierge.fail('invalid_input');end if;
 for c in select value from jsonb_array_elements(cards) loop
  if c->>'kind'='addition' then
   if c->'currentProduct'<>'null'::jsonb or c->'proposedProduct'='null'::jsonb or c->'usage'='null'::jsonb or c->'recommendationId'='null'::jsonb
    or exists(select 1 from jsonb_array_elements(baseline)j(b) where b->>'slot'=c->>'slot')
    or exists(select 1 from jsonb_array_elements(steps)j(s) where j.s->>'id'=c->>'id') then perform concierge.fail('invalid_input');end if;
  elsif c->>'kind'='optional_alternative' then
   if c->'currentProduct'='null'::jsonb or c->'proposedProduct'='null'::jsonb or c->'usage'='null'::jsonb
    or not exists(select 1 from jsonb_array_elements(baseline)j(b) where b->>'slot'=c->>'slot' and b->>'productId'=c->'currentProduct'->>'id') then perform concierge.fail('invalid_input');end if;
  elsif c->>'kind' in ('pause','leave_out') then
   if c->'currentProduct'='null'::jsonb or c->'recommendationId'<>'null'::jsonb or c->'usage'<>'null'::jsonb or (c->>'kind'='leave_out' and c->'proposedProduct'<>'null'::jsonb) then perform concierge.fail('invalid_input');end if;
  elsif c->>'kind'='no_addition' then
   if c->'recommendationId'<>'null'::jsonb or c->'currentProduct'<>'null'::jsonb or c->'proposedProduct'<>'null'::jsonb or c->'usage'<>'null'::jsonb then perform concierge.fail('invalid_input');end if;
  else
   if c->'currentProduct'='null'::jsonb or c->'usage'='null'::jsonb then perform concierge.fail('invalid_input');end if;
   if c->>'kind'='keep' then
    if c->'recommendationId'<>'null'::jsonb or c->'proposedProduct'<>'null'::jsonb then perform concierge.fail('invalid_input');end if;
   elsif c->'proposedProduct'='null'::jsonb or (c->>'kind'='replace' and c->'recommendationId'='null'::jsonb) then perform concierge.fail('invalid_input');end if;
   if not exists(select 1 from jsonb_array_elements(baseline)j(b) where b->>'slot'=c->>'slot' and b->>'productId'=c->'currentProduct'->>'id') then perform concierge.fail('invalid_input');end if;
  end if;
  if c->>'recommendationId' is not null and (c->>'kind' not in ('replace','finish_then_replace','addition','optional_alternative') or (c->>'kind' in ('addition','optional_alternative') and c->'proposedProduct'->'displayPrice'='null'::jsonb)) then perform concierge.fail('invalid_input');end if;
 end loop;
 if recs is not null then
  if (select count(*) from jsonb_array_elements(cards)j(x) where x->>'recommendationId' is not null)<>jsonb_array_length(recs) then perform concierge.fail('invalid_input');end if;
  for r in select value from jsonb_array_elements(recs) loop
   select value into c from jsonb_array_elements(cards) where value->>'recommendationId'=r->>'id';
   if not found or c->>'slot' is distinct from r->>'slot' or c->'currentProduct'->>'id' is distinct from r->>'currentProductId' or c->'proposedProduct'->>'id' is distinct from r->>'proposedProductId' or c->'usage'='null'::jsonb then perform concierge.fail('invalid_input');end if;
   if c->'proposedProduct'->'displayPrice'<>'null'::jsonb and c->'proposedProduct'->'displayPrice'->'cents' is distinct from r->'priceCents' then perform concierge.fail('invalid_input');end if;
  end loop;
 end if;
 for g in select value from jsonb_array_elements(p->'routineGuides') union all select x->'how' from jsonb_array_elements(cards)j(x) loop
  pid:=g->>'productId';
  if pid is not null and not exists(select 1 from jsonb_array_elements(steps)j(x) where x->>'productId'=pid) and not exists(select 1 from jsonb_array_elements(cards)j(x) where x->'currentProduct'->>'id'=pid or x->'proposedProduct'->>'id'=pid) then perform concierge.fail('invalid_input');end if;
 end loop;
end $$;

create or replace function public.concierge_write(p_client_id uuid,p_action text,p_expected_revision bigint,p_request_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ begin
 if p_action in ('save_draft','publish') then
  perform concierge.access(p_client_id,case when p_action='publish' then 'publish' else 'edit' end,true);
  perform pg_advisory_xact_lock(hashtextextended('concierge:request:'||auth.uid()::text||':'||p_request_id::text,0));
  perform pg_advisory_xact_lock(hashtextextended('concierge:client:'||p_client_id::text,0));
  if concierge.has_presentation(p_client_id) then perform concierge.fail('content_version_required');end if;
  -- Null current identity belongs only to the fully bound R2 addition contract.
  if p_action='save_draft' and exists(select 1 from jsonb_array_elements(p_payload->'recommendations')j(r) where r->'currentProductId'='null'::jsonb) then perform concierge.fail('invalid_input');end if;
 end if;
 return concierge.r1_workflow_write(p_client_id,p_action,p_expected_revision,p_request_id,p_payload);
end $$;

create or replace function public.concierge_presentation_write(p_client_id uuid,p_action text,p_expected_revision bigint,p_request_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;prior jsonb;c concierge.cases;baseline jsonb;r jsonb;iv integer;result jsonb;p jsonb;g text;n text;begin
 if p_action is null or p_action not in ('save_intake_v2','save_draft_v2','publish_v2') then perform concierge.fail('invalid_input');end if;
 u:=concierge.access(p_client_id,case when p_action='publish_v2' then 'publish' else 'edit' end,true);
 prior:=concierge.workflow_begin(u,p_client_id,p_request_id,'presentation',p_action,p_expected_revision,p_payload);if prior is not null then return prior;end if;
 select * into c from concierge.cases where client_id=p_client_id for update;
 if c.revision<>p_expected_revision then perform concierge.fail('revision_conflict');end if;
 if p_action='save_intake_v2' then
  perform concierge.keys(p_payload,array['goal','note','baseline','presentation']);g:=concierge.txt(p_payload,'goal',300);n:=concierge.txt(p_payload,'note',4000,true);baseline:=p_payload->'baseline';
  if jsonb_typeof(baseline) is distinct from 'array' then perform concierge.fail('invalid_input');end if;
  if jsonb_array_length(baseline) not between 1 and 50 or (select count(distinct x->>'slot') from jsonb_array_elements(baseline)j(x))<>jsonb_array_length(baseline) then perform concierge.fail('invalid_input');end if;
  for r in select value from jsonb_array_elements(baseline) loop
   perform concierge.keys(r,array['slot','productId']);perform concierge.identifier(concierge.txt(r,'slot',100));perform concierge.identifier(concierge.txt(r,'productId',100));
  end loop;
  if exists(select 1 from concierge.intakes where client_id=p_client_id) and ((select count(*) from concierge.baselines where client_id=p_client_id)<>jsonb_array_length(baseline) or exists(select 1 from concierge.baselines b where b.client_id=p_client_id and not exists(select 1 from jsonb_array_elements(baseline)j(x) where x->>'slot'=b.slot and x->>'productId'=b.product_id))) then perform concierge.fail('baseline_conflict');end if;
  perform concierge.validate_presentation(p_payload->'presentation',baseline,null,true);
  insert into concierge.baselines select p_client_id,x->>'slot',x->>'productId' from jsonb_array_elements(baseline)j(x) on conflict do nothing;
  select coalesce(max(version),0)+1 into iv from concierge.intakes where client_id=p_client_id;
  insert into concierge.intakes(client_id,version,goal,note) values(p_client_id,iv,g,n);
  insert into concierge.intake_presentations values(p_client_id,iv,p_payload->'presentation');
  update concierge.cases set revision=revision+1 where client_id=p_client_id;
 elsif p_action='save_draft_v2' then
  perform concierge.keys(p_payload,array['intakeVersion','recommendations','advisorNote','presentation']);
  select coalesce(jsonb_agg(jsonb_build_object('slot',slot,'productId',product_id)),'[]') into baseline from concierge.baselines where client_id=p_client_id;
  perform concierge.validate_items(p_payload->'recommendations');perform concierge.validate_presentation(p_payload->'presentation',baseline,p_payload->'recommendations');
  if exists(select 1 from jsonb_array_elements((p_payload->'presentation')->'categoryCards')j(card) where card->>'kind'='addition' and (
   exists(select 1 from concierge.publication_presentations pp cross join lateral jsonb_array_elements(pp.presentation->'baselineRoutine')j(step) where pp.client_id=p_client_id and step->>'id'=card->>'id')
   or exists(select 1 from concierge.activations ac join concierge.publication_presentations pp on pp.client_id=ac.client_id and pp.version=ac.version
    cross join lateral jsonb_array_elements(pp.presentation->'categoryCards')j(prior_card)
    where ac.client_id=p_client_id and ac.slot<>card->>'slot' and prior_card->>'recommendationId'=ac.recommendation_id and prior_card->>'id'=card->>'id'
     and not exists(select 1 from concierge.baselines b where b.client_id=p_client_id and b.slot=ac.slot))
  )) then perform concierge.fail('invalid_input');end if;
  if (select count(*) from (
   select slot from concierge.baselines where client_id=p_client_id
   union select slot from concierge.activations where client_id=p_client_id
   union select card->>'slot' from jsonb_array_elements((p_payload->'presentation')->'categoryCards')j(card) where card->>'kind'='addition'
  )slots)+(select max(instructions) from (
   select count(*) instructions from jsonb_array_elements((p_payload->'presentation')->'baselineRoutine')j(step) where step->>'kind'='instruction'
   union all select (select count(*) from jsonb_array_elements(pp.presentation->'baselineRoutine')j(step) where step->>'kind'='instruction') from concierge.publication_presentations pp where pp.client_id=p_client_id
  )snapshots)>50 then perform concierge.fail('invalid_input');end if;
  -- R2 addition slots have no baseline row. The full presentation validator
  -- above binds null current identities; keep the same transactional intake fence.
  iv:=concierge.integer(p_payload,'intakeVersion');n:=concierge.txt(p_payload,'advisorNote',4000,true);
  if iv is distinct from (select max(version) from concierge.intakes where client_id=p_client_id) then perform concierge.fail('intake_conflict');end if;
  insert into concierge.drafts values(p_client_id,iv,concierge.public_items(p_payload->'recommendations'),n)
   on conflict(client_id) do update set intake_version=excluded.intake_version,recommendations=excluded.recommendations,advisor_note=excluded.advisor_note;
  update concierge.cases set revision=revision+1 where client_id=p_client_id;
  insert into concierge.draft_presentations values(p_client_id,(p_payload->>'intakeVersion')::integer,p_payload->'presentation') on conflict(client_id) do update set intake_version=excluded.intake_version,presentation=excluded.presentation;
 else
  perform concierge.keys(p_payload,array[]::text[]);
  select dp.presentation,d.recommendations into p,r from concierge.draft_presentations dp join concierge.drafts d on d.client_id=dp.client_id and d.intake_version=dp.intake_version where dp.client_id=p_client_id;
  if not found then perform concierge.fail('content_version_required');end if;
  -- Revalidate persisted content as well as new writes before publication.
  select coalesce(jsonb_agg(jsonb_build_object('slot',slot,'productId',product_id)),'[]') into baseline from concierge.baselines where client_id=p_client_id;
  perform concierge.validate_items(r);perform concierge.validate_presentation(p,baseline,r);
  if exists(select 1 from jsonb_array_elements(p->'categoryCards')j(card) where card->>'kind'='addition' and (
   exists(select 1 from concierge.publication_presentations pp cross join lateral jsonb_array_elements(pp.presentation->'baselineRoutine')j(step) where pp.client_id=p_client_id and step->>'id'=card->>'id')
   or exists(select 1 from concierge.activations ac join concierge.publication_presentations pp on pp.client_id=ac.client_id and pp.version=ac.version
    cross join lateral jsonb_array_elements(pp.presentation->'categoryCards')j(prior_card)
    where ac.client_id=p_client_id and ac.slot<>card->>'slot' and prior_card->>'recommendationId'=ac.recommendation_id and prior_card->>'id'=card->>'id'
     and not exists(select 1 from concierge.baselines b where b.client_id=p_client_id and b.slot=ac.slot))
  )) then perform concierge.fail('invalid_input');end if;
  if (select count(*) from (
   select slot from concierge.baselines where client_id=p_client_id
   union select slot from concierge.activations where client_id=p_client_id
   union select card->>'slot' from jsonb_array_elements(p->'categoryCards')j(card) where card->>'kind'='addition'
  )slots)+(select max(instructions) from (
   select count(*) instructions from jsonb_array_elements(p->'baselineRoutine')j(step) where step->>'kind'='instruction'
   union all select (select count(*) from jsonb_array_elements(pp.presentation->'baselineRoutine')j(step) where step->>'kind'='instruction') from concierge.publication_presentations pp where pp.client_id=p_client_id
  )snapshots)>50 then perform concierge.fail('invalid_input');end if;
  result:=concierge.r1_workflow_write(p_client_id,'publish',p_expected_revision,p_request_id,'{}');
  insert into concierge.publication_presentations values(p_client_id,(result->>'publishedVersion')::integer,p);
 end if;
 select * into c from concierge.cases where client_id=p_client_id;
 result:=jsonb_build_object('revision',c.revision,'publishedVersion',c.published_version,'operation',p_action);
 return concierge.workflow_finish(u,p_client_id,p_request_id,'presentation',p_action,p_expected_revision,p_payload,result);
end $$;

create or replace function concierge.client_projection(c uuid) returns jsonb language plpgsql set search_path='' as $$
declare rev bigint;v integer;items jsonb:='[]';plan jsonb;history jsonb;states jsonb;orders jsonb;routine jsonb;starts jsonb; begin
 select revision,published_version into rev,v from concierge.cases where client_id=c for share;
 if not found then return jsonb_build_object('revision',0,'plan',null,'history','[]'::jsonb,'orderProposal',jsonb_build_object('kind','proposal','currency','USD','items','[]'::jsonb,'subtotalCents',0,'payable',false,'shippingAndTaxConfirmed',false),'routine','[]'::jsonb,'routineHistory','[]'::jsonb);end if;
 if v>0 then
  select recommendations into items from concierge.publications where client_id=c and version=v;
  select coalesce(jsonb_agg(jsonb_build_object('recommendationId',r->>'id','choice',s.choice,'reason',s.reason,'received',o.client_id is not null,'startedOn',a.started_on) order by n),'[]') into states
   from jsonb_array_elements(items) with ordinality j(r,n) join concierge.item_states s on s.client_id=c and s.version=v and s.recommendation_id=r->>'id'
   left join concierge.receipts o on o.client_id=c and o.slot=r->>'slot' and o.product_id=r->>'proposedProductId' left join concierge.activations a on a.id=s.activation_id;
  plan:=jsonb_build_object('version',v,'recommendations',concierge.public_items(items),'itemStates',states);
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('version',version,'recommendations',concierge.public_items(recommendations)) order by version),'[]') into history from concierge.publications where client_id=c and version<v;
 select coalesce(jsonb_agg(r order by n),'[]') into orders from jsonb_array_elements(concierge.public_items(items)) with ordinality j(r,n)
  join concierge.item_states s on s.client_id=c and s.version=v and s.recommendation_id=r->>'id' and s.choice='approved'
  where not exists(select 1 from concierge.receipts o where o.client_id=c and o.slot=r->>'slot' and o.product_id=r->>'proposedProductId');
 select coalesce(jsonb_agg(jsonb_build_object('slot',slots.slot,'productId',coalesce(a.product_id,b.product_id)) order by slots.slot),'[]') into routine
  from (select slot from concierge.baselines where client_id=c union select slot from concierge.activations where client_id=c and version<=v and started_on<=(now() at time zone 'UTC')::date) slots
  left join concierge.baselines b on b.client_id=c and b.slot=slots.slot
  left join lateral(select product_id from concierge.activations where client_id=c and slot=slots.slot and version<=v and started_on<=(now() at time zone 'UTC')::date order by started_on desc,id desc limit 1)a on true
  where coalesce(a.product_id,b.product_id) is not null;
 select coalesce(jsonb_agg(jsonb_build_object('version',version,'recommendationId',recommendation_id,'slot',slot,'productId',product_id,'startedOn',started_on) order by started_on,id),'[]') into starts from concierge.activations where client_id=c;
 return jsonb_build_object('revision',rev,'plan',plan,'history',history,'orderProposal',jsonb_build_object('kind','proposal','currency','USD','items',orders,'subtotalCents',(select coalesce(sum((r->>'priceCents')::bigint),0) from jsonb_array_elements(orders) j(r)),'payable',false,'shippingAndTaxConfirmed',false),'routine',routine,'routineHistory',starts);
end $$;

create or replace function concierge.portal_projection(c uuid) returns jsonb language plpgsql set search_path='' as $$
declare rev bigint;v integer;items jsonb:='[]';plan jsonb;history jsonb;states jsonb;orders jsonb;routine jsonb;starts jsonb;begin
 select revision into rev from concierge.cases where client_id=c for share;
 select coalesce(max(version),0) into v from concierge.entitled_publications where client_id=c and starts_on<=(now() at time zone 'America/Chicago')::date;
 if v=0 then return jsonb_build_object('revision',coalesce(rev,0),'plan',null,'history','[]'::jsonb,'orderProposal',jsonb_build_object('kind','proposal','currency','USD','items','[]'::jsonb,'subtotalCents',0,'payable',false,'shippingAndTaxConfirmed',false),'routine','[]'::jsonb,'routineHistory','[]'::jsonb);end if;
 select recommendations into items from concierge.publications where client_id=c and version=v;
 select coalesce(jsonb_agg(jsonb_build_object('recommendationId',r->>'id','choice',s.choice,'reason',s.reason,'received',o.client_id is not null,'startedOn',a.started_on) order by n),'[]') into states
  from jsonb_array_elements(items) with ordinality j(r,n) join concierge.item_states s on s.client_id=c and s.version=v and s.recommendation_id=r->>'id'
  left join concierge.receipts o on o.client_id=c and o.slot=r->>'slot' and o.product_id=r->>'proposedProductId' left join concierge.activations a on a.id=s.activation_id;
 plan:=jsonb_build_object('version',v,'recommendations',concierge.public_items(items),'itemStates',states);
 select coalesce(jsonb_agg(jsonb_build_object('version',p.version,'recommendations',concierge.public_items(p.recommendations)) order by p.version),'[]') into history
  from concierge.publications p join concierge.entitled_publications e on e.client_id=p.client_id and e.version=p.version where p.client_id=c and p.version<v and e.starts_on<=(now() at time zone 'America/Chicago')::date;
 select coalesce(jsonb_agg(r order by n),'[]') into orders from jsonb_array_elements(concierge.public_items(items)) with ordinality j(r,n)
  join concierge.item_states s on s.client_id=c and s.version=v and s.recommendation_id=r->>'id' and s.choice='approved'
  where not exists(select 1 from concierge.receipts o where o.client_id=c and o.slot=r->>'slot' and o.product_id=r->>'proposedProductId');
 select coalesce(jsonb_agg(jsonb_build_object('slot',slots.slot,'productId',coalesce(a.product_id,b.product_id)) order by slots.slot),'[]') into routine
  from (select slot from concierge.baselines where client_id=c union select slot from concierge.activations ac where ac.client_id=c and ac.version<=v and ac.started_on<=(now() at time zone 'UTC')::date and exists(select 1 from concierge.entitled_publications e where e.client_id=ac.client_id and e.version=ac.version and e.starts_on<=(now() at time zone 'America/Chicago')::date)) slots
  left join concierge.baselines b on b.client_id=c and b.slot=slots.slot
  left join lateral(select ac.product_id from concierge.activations ac where ac.slot=slots.slot and ac.client_id=c and ac.version<=v and ac.started_on<=(now() at time zone 'UTC')::date and exists(select 1 from concierge.entitled_publications e where e.client_id=ac.client_id and e.version=ac.version and e.starts_on<=(now() at time zone 'America/Chicago')::date) order by ac.started_on desc,ac.id desc limit 1)a on true
  where coalesce(a.product_id,b.product_id) is not null;
 select coalesce(jsonb_agg(jsonb_build_object('version',a.version,'recommendationId',a.recommendation_id,'slot',a.slot,'productId',a.product_id,'startedOn',a.started_on) order by a.started_on,a.id),'[]') into starts from concierge.activations a join concierge.entitled_publications e on e.client_id=a.client_id and e.version=a.version where a.client_id=c and a.version<=v and e.starts_on<=(now() at time zone 'America/Chicago')::date;
 return jsonb_build_object('revision',rev,'plan',plan,'history',history,'orderProposal',jsonb_build_object('kind','proposal','currency','USD','items',orders,'subtotalCents',(select coalesce(sum((r->>'priceCents')::bigint),0) from jsonb_array_elements(orders)j(r)),'payable',false,'shippingAndTaxConfirmed',false),'routine',routine,'routineHistory',starts);
end $$;

create or replace function concierge.presentation_projection(c uuid,v jsonb,advisor boolean default false) returns jsonb language plpgsql set search_path='' as $$
declare plan jsonb:=v->'plan';history jsonb;baseline jsonb;baseline_version integer;active jsonb:='[]';r jsonb;s jsonb;p jsonb;card jsonb;guides jsonb;a concierge.activations;begin
 if plan<>'null'::jsonb then
  select presentation into p from concierge.publication_presentations where client_id=c and version=(plan->>'version')::integer;
  plan:=plan||jsonb_build_object('presentation',p);
 end if;
 select coalesce(jsonb_agg(x||jsonb_build_object('presentation',pp.presentation) order by n),'[]') into history from jsonb_array_elements(v->'history') with ordinality j(x,n)
 left join concierge.publication_presentations pp on pp.client_id=c and pp.version=(x->>'version')::integer;
 if plan<>'null'::jsonb then
  -- Earliest entitled rich baseline, never latest draft or an unpaid snapshot.
  select pp.presentation,pp.version into baseline,baseline_version from concierge.publication_presentations pp
   where pp.client_id=c and (advisor or exists(select 1 from concierge.entitled_publications e where e.client_id=c and e.version=pp.version and e.starts_on<=(now() at time zone 'America/Chicago')::date))
   order by pp.version limit 1;
  for r in select value from jsonb_array_elements(v->'routine') loop
   select ac.* into a from concierge.activations ac where ac.client_id=c and ac.slot=r->>'slot' and ac.started_on<=(now() at time zone 'UTC')::date
    and (advisor or exists(select 1 from concierge.entitled_publications e where e.client_id=c and e.version=ac.version and e.starts_on<=(now() at time zone 'America/Chicago')::date))
    order by ac.started_on desc,ac.id desc limit 1;
   if found then
    select presentation into p from concierge.publication_presentations where client_id=c and version=a.version;
    select value into card from jsonb_array_elements(p->'categoryCards') where value->>'recommendationId'=a.recommendation_id and value->'proposedProduct'->>'id'=r->>'productId';
    if card is null then continue;end if;
    s:=jsonb_build_object('id',coalesce((select x->>'id' from jsonb_array_elements(baseline->'baselineRoutine')j(x) where x->>'kind'='product' and x->>'slot'=a.slot),card->>'id'),'kind','product','slot',a.slot,'productId',a.product_id,'product',card->'proposedProduct','title',card->'proposedProduct'->>'name','usage',card->'usage',
     'source',jsonb_build_object('kind','activation','publicationVersion',a.version,'recommendationId',a.recommendation_id));
    select coalesce(jsonb_agg(g),'[]') into guides from (select value g from jsonb_array_elements(p->'routineGuides') union all select card->'how')j
     where g->>'productId' is null or g->>'productId'=a.product_id;
   else
    select value into s from jsonb_array_elements(baseline->'baselineRoutine') where value->>'slot'=r->>'slot' and value->>'productId'=r->>'productId';
    if s is null then continue;end if;
    s:=s||jsonb_build_object('source',jsonb_build_object('kind','baseline','publicationVersion',baseline_version,'recommendationId',null));
    select coalesce(jsonb_agg(g),'[]') into guides from (select value g from jsonb_array_elements(baseline->'routineGuides') union all select value->'how' from jsonb_array_elements(baseline->'categoryCards') where value->'currentProduct'->>'id'=r->>'productId')j
     where g->>'productId' is null or g->>'productId'=r->>'productId';
   end if;
   active:=active||jsonb_build_array(s||jsonb_build_object('guides',guides));
  end loop;
  for s in select value from jsonb_array_elements(baseline->'baselineRoutine') where value->>'kind'='instruction' loop
   active:=active||jsonb_build_array(s||jsonb_build_object('source',jsonb_build_object('kind','baseline','publicationVersion',baseline_version,'recommendationId',null),'guides','[]'::jsonb));
  end loop;
 end if;
 return v||jsonb_build_object('schemaVersion',2,'plan',plan,'history',history,'activeRoutine',active);
end $$;
commit;
